export function getCommentsForArticle(slugOrId: string, title?: string): CommentItem[] {
  if (!slugOrId) return [];
  const direct = ARTICLES_COMMENTS_MAP[slugOrId] || ARTICLES_COMMENTS_MAP[decodeURIComponent(slugOrId)];
  if (direct && direct.length > 0) return direct;

  // Search by title or partial slug
  for (const [key, val] of Object.entries(ARTICLES_COMMENTS_MAP)) {
    if (slugOrId.toLowerCase().includes(key.toLowerCase()) || (title && val[0]?.target_title?.includes(title))) {
      return val;
    }
  }

  // Fallback to first available
  return Object.values(ARTICLES_COMMENTS_MAP)[0] || [];
}
